$new3 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old3) -lt 0) { throw "Bloco 3 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old3, $new3)

# --- Bloco 4 ---
$old4 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String('ICAgICAgICAgICAgICAgIDx0cj48dGg+UGFjaWVudGU8L3RoPjx0aD5UZWxlZm9uZTwvdGg+PHRoIHN0eWxlPXt7IHRleHRBbGlnbjonY2VudGVyJyB9fT5Db25zdWx0YXM8L3RoPjx0aCBzdHlsZT17eyB0ZXh0QWxpZ246J2NlbnRlcicgfX0+w5psdGltYSBjb25zdWx0YTwvdGg+PC90cj4='))
$new4 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String('ICAgICAgICAgICAgICAgIDx0cj48dGg+UGFjaWVudGU8L3RoPjx0aD5UZWxlZm9uZTwvdGg+PHRoIHN0eWxlPXt7IHRleHRBbGlnbjonY2VudGVyJyB9fT5Db25zdWx0YXM8L3RoPjx0aCBzdHlsZT17eyB0ZXh0QWxpZ246J2NlbnRlcicgfX0+w5psdGltYSBjb25zdWx0YTwvdGg+PHRoIHN0eWxlPXt7IHRleHRBbGlnbjoncmlnaHQnIH19PkHDp8O1ZXM8L3RoPjwvdHI+'))
if ($content.IndexOf($old4) -lt 0) { throw "Bloco 4 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old4, $new4)

# --- Bloco 5 ---
$old5 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
$new5 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old5) -lt 0) { throw "Bloco 5 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old5, $new5)

# --- Bloco 6 ---
$old6 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
$new6 = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
if ($content.IndexOf($old6) -lt 0) { throw "Bloco 6 nao encontrado no arquivo - patch abortado, nada foi alterado." }
$content = $content.Replace($old6, $new6)

if ($hadCRLF) { $content = $content -replace "`n", "`r`n" }

if ($hasBom) {
  $utf8Bom = New-Object System.Text.UTF8Encoding($true)
  [System.IO.File]::WriteAllText($path, $content, $utf8Bom)
} else {
  $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($path, $content, $utf8NoBom)
}

Write-Host "PacientesTab.tsx atualizado: botao Atender + modal Iniciar Atendimento (Profissional + Procedimento) adicionados."
